package com.example.atlantvpn

import java.security.GeneralSecurityException
import javax.crypto.Cipher
import javax.crypto.SecretKey
import javax.crypto.spec.GCMParameterSpec

// Standard AES-GCM envelope. The preference name is authenticated so swapping
// two encrypted preference values fails. IVs are generated by the provider.
internal object ProtectedPreferenceCodec {
    private const val IV_BYTES = 12
    private const val MAX_BYTES = 8 * 1024 * 1024

    fun seal(key: SecretKey, name: String, plain: ByteArray): ByteArray {
        require(plain.size <= MAX_BYTES)
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        cipher.init(Cipher.ENCRYPT_MODE, key)
        cipher.updateAAD("atlant-prefs-v1:$name".toByteArray(Charsets.UTF_8))
        check(cipher.iv.size == IV_BYTES)
        return byteArrayOf(1) + cipher.iv + cipher.doFinal(plain)
    }

    fun open(key: SecretKey, name: String, envelope: ByteArray): ByteArray {
        if (envelope.size < 1 + IV_BYTES + 16 || envelope.size > MAX_BYTES + 29 || envelope[0] != 1.toByte()) {
            throw GeneralSecurityException("Invalid encrypted preference")
        }
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        cipher.init(Cipher.DECRYPT_MODE, key, GCMParameterSpec(128, envelope.copyOfRange(1, 13)))
        cipher.updateAAD("atlant-prefs-v1:$name".toByteArray(Charsets.UTF_8))
        return cipher.doFinal(envelope, 13, envelope.size - 13)
    }
}
